CREATE TABLE IF NOT EXISTS "taobao_product_prices" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "shop_name" varchar(255) NOT NULL,
  "product_url" varchar(1000) NOT NULL,
  "item_name" varchar(500) NOT NULL,
  "price" numeric(12,2) NOT NULL,
  "scraped_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "UQ_taobao_product_price_item" UNIQUE ("product_url", "item_name"),
  CONSTRAINT "CHK_taobao_product_price_nonnegative" CHECK ("price" >= 0)
);

CREATE INDEX IF NOT EXISTS "IDX_taobao_product_prices_scraped_at"
  ON "taobao_product_prices" ("scraped_at" DESC, "id" DESC);

CREATE INDEX IF NOT EXISTS "IDX_taobao_product_prices_shop_name"
  ON "taobao_product_prices" ("shop_name");
